    #[test]
    fn migration_assets_and_first_party_table_have_no_legacy_name_wiring() {
        let first_party = include_str!("first_party.rs");
        assert!(!first_party.contains("crush"));
        assert!(!first_party.contains("maki"));
        let templates = include_str!("../../../src/data/templates/mod.rs");
        for legacy in [
            "Dockerfile.crush",
            "Dockerfile.maki",
            "sbx-kit.crush",
            "sbx-kit.maki",
            "sbx-apply.crush",
            "sbx-apply.maki",
        ] {
            assert!(
                !templates.contains(legacy),
                "stale embedded template reference: {legacy}"
            );
        }
    }
